// This file is generated by AI.

// 差异色块的行装饰: 把行改动 (A/M/D) 映射成 Monaco 的整行装饰。
//
// 两个来源共用这一份: git 行内差异 (后端 `git_file_changes`) 与文本预处理各步的改动
// (前端 `editor/line-diff`), 因此这里只认 `{ line, kind }`。

import type { LineChange, LineChangeKind } from './line-diff';

/** 每类改动对应的高亮 class (样式见 styles.css) */
export const DIFF_GUTTER_CLASS: Record<LineChangeKind, string> = {
  A: 'diff-gutter-added',
  M: 'diff-gutter-modified',
  D: 'diff-gutter-deleted',
};

/** 一条待画的色块 */
export interface DiffGutterMark {
  /** 1 起算、已夹到文档范围内的行号 */
  lineNumber: number;
  /** 行末列号 —— 区间必须覆盖整行, 原因见 [`diffGutterMarks`] */
  endColumn: number;
  className: string;
}

/**
 * 把行改动换算成待画的行装饰。
 *
 * **区间必须覆盖整行**, 不能只给一个零长度区间 (`(line,1)-(line,1)`):
 * Monaco 会把装饰区间换算到视觉行坐标 (见 viewModelDecorations 里 `isWholeLine` 的分支),
 * 折叠区间只会落在折出来的**第一行**上 —— 开启自动换行后, 长行的色块就只有首行有颜色。
 * 因此这里一律取到 `lineMaxColumn`; 顺带行号也可能超出文档 (文档比差异来源短) 需要夹住。
 */
export function diffGutterMarks(
  changes: readonly LineChange[],
  lineCount: number,
  lineMaxColumn: (lineNumber: number) => number
): DiffGutterMark[] {
  const count = Math.max(1, lineCount);
  return changes.map((change) => {
    const lineNumber = Math.min(Math.max(1, change.line), count);
    return {
      lineNumber,
      endColumn: Math.max(1, lineMaxColumn(lineNumber)),
      className: DIFF_GUTTER_CLASS[change.kind],
    };
  });
}
